const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const ws = wb.Sheets[wb.SheetNames[0]];
const rows = XLSX.utils.sheet_to_json(ws);

// Stats
const total = rows.length;
const confirmed = rows.filter(r => r.Status === 'confirmed').length;
const cancelled = rows.filter(r => r.Status === 'cancelled').length;
const totalRev = rows.filter(r => r.Status === 'confirmed').reduce((s,r) => s + (r['Total Paid']||0), 0);
const totalAll = rows.reduce((s,r) => s + (r['Total Paid']||0), 0);

// Unique customers
const customers = [...new Set(rows.map(r => r.Customer))];
const confirmedRows = rows.filter(r => r.Status === 'confirmed');

// Top customers by revenue
const custRev = {};
confirmedRows.forEach(r => { custRev[r.Customer] = (custRev[r.Customer]||0) + r['Total Paid']; });
const topCust = Object.entries(custRev).sort((a,b)=>b[1]-a[1]).slice(0,5);

// Item frequency
const itemCount = {};
confirmedRows.forEach(r => {
  const items = String(r.Items).split(',').map(s=>s.trim());
  items.forEach(i => { itemCount[i] = (itemCount[i]||0) + 1; });
});
const topItems = Object.entries(itemCount).sort((a,b)=>b[1]-a[1]).slice(0,5);

// Dates
const dates = [...new Set(rows.map(r => r.Date))];

console.log(JSON.stringify({total, confirmed, cancelled, totalRev, totalAll, customers: customers.length, topCust, topItems, dates}, null, 2));
"

